/**
 * Generate the server-side price list used by the payment edge function.
 *
 *   node scripts/sync-prices.mjs
 *
 * WHY THIS EXISTS
 * ---------------
 * Prices must never be trusted from the browser: a customer could otherwise
 * submit `total: 1` and walk away with ₹3000 of stock. `trios-pay` therefore
 * recomputes every order from this file, which is derived from the single
 * source of truth (`src/data/catalog.ts`).
 *
 * Run this after editing the catalog, and before deploying the function.
 * CI can diff the generated file to catch drift.
 */
import esbuild from 'esbuild';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';
import { writeFileSync, mkdirSync } from 'node:fs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Bundle the catalog to plain ESM so we can import the real PRODUCTS array
// instead of parsing TypeScript with a regex.
const result = await esbuild.build({
  entryPoints: [path.join(root, 'src/data/catalog.ts')],
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  write: false,
});

const outFile = path.join(root, 'node_modules/.cache', `catalog-${Date.now()}.mjs`);
mkdirSync(path.dirname(outFile), { recursive: true });
writeFileSync(outFile, result.outputFiles[0].text);
const { PRODUCTS } = await import(pathToFileURL(outFile).href);

const entries = PRODUCTS.map((p) => {
  const sizes = {};
  for (const variant of p.variants) {
    for (const s of variant.sizes) {
      sizes[s.size] = Math.max(sizes[s.size] ?? 0, s.stock);
    }
  }
  return {
    id: p.id,
    name: p.name,
    slug: p.slug,
    price: p.price,
    mrp: p.mrp,
    sizes,
    colors: p.variants.map((v) => v.color),
  };
});

const header = `/**
 * AUTO-GENERATED by \`node scripts/sync-prices.mjs\` - DO NOT EDIT BY HAND.
 *
 * Authoritative catalogue pricing for the payment edge function. Every order
 * is repriced from this map on the server before a payment is created, so a
 * tampered client payload can never change what the customer actually pays.
 *
 * Source of truth: src/data/catalog.ts
 * Products: ${entries.length}
 */
export interface PriceEntry {
  name: string;
  slug: string;
  price: number;
  mrp: number;
  sizes: Record<string, number>;
  colors: string[];
}

export const PRICES: Record<string, PriceEntry> = `;

const body = entries
  .map(
    (e) =>
      `  ${JSON.stringify(e.id)}: { name: ${JSON.stringify(e.name)}, slug: ${JSON.stringify(e.slug)}, price: ${e.price}, mrp: ${e.mrp}, sizes: ${JSON.stringify(e.sizes)}, colors: ${JSON.stringify(e.colors)} },`,
  )
  .join('\n');

const target = path.join(root, 'supabase/functions/_shared/prices.ts');
mkdirSync(path.dirname(target), { recursive: true });
writeFileSync(target, `${header}{\n${body}\n};\n`);

console.log(`sync-prices: wrote ${entries.length} products to supabase/functions/_shared/prices.ts`);
